import { Separator as BaseSeparator } from '@base-ui/react/separator';
import type { ReactNode, Ref } from 'react';
import { cn } from '../../utils/cn';
import { separatorVariants, type SeparatorVariantProps } from './separator.variants';

export interface SeparatorProps extends Omit<BaseSeparator.Props, 'className'>, SeparatorVariantProps {
  className?: string;
  ref?: Ref<HTMLDivElement>;
  /** Text (or icon) set into a horizontal line, e.g. a date or section kicker. */
  label?: ReactNode;
  /** Where the label sits along the line. */
  labelPosition?: 'start' | 'center' | 'end';
}

/**
 * Thematic break between content (role="separator"). Horizontal or vertical; a horizontal
 * separator can carry a label. Purely decorative dividers can pass `render={<div aria-hidden />}`.
 */
export function Separator({
  orientation = 'horizontal',
  variant,
  labelStyle,
  label,
  labelPosition = 'center',
  className,
  ...props
}: SeparatorProps) {
  const s = separatorVariants({ orientation, variant, labelStyle });
  if (label == null || orientation === 'vertical') {
    return <BaseSeparator orientation={orientation} className={cn(s.line(), className)} {...props} />;
  }
  const line = s.line({ class: 'w-auto flex-1' });
  return (
    <div className={cn(s.labelled(), className)}>
      {labelPosition !== 'start' && <BaseSeparator orientation="horizontal" className={line} {...props} />}
      <span className={s.label()}>{label}</span>
      {labelPosition !== 'end' && (
        labelPosition === 'start'
          ? <BaseSeparator orientation="horizontal" className={line} {...props} />
          : <span aria-hidden className={line} />
      )}
    </div>
  );
}

export { Separator, type SeparatorProps } from './Separator';
export { separatorVariants, type SeparatorVariantProps } from './separator.variants';
export { doc as separatorDoc } from './Separator.doc';

import { tv, type VariantProps } from '../../utils/tv';

export const separatorVariants = tv({
  slots: {
    line: 'shrink-0 border-0',
    labelled: 'flex w-full items-center gap-3',
    label: 'shrink-0',
  },
  variants: {
    orientation: {
      horizontal: { line: 'h-px w-full' },
      vertical: { line: 'w-px self-stretch' },
    },
    variant: {
      default: { line: 'bg-border' },
      subtle: { line: 'bg-border/50' },
      strong: { line: 'rounded-full bg-border' },
    },
    labelStyle: {
      plain: { label: 'text-[12.5px] text-muted-foreground' },
      kicker: { label: 'font-mono text-[10.5px] tracking-[0.14em] text-muted-foreground uppercase' },
      pill: { label: 'inline-flex h-[22px] items-center rounded-full bg-secondary px-2.5 font-mono text-[10.5px] font-semibold text-muted-foreground' },
    },
  },
  compoundVariants: [
    { orientation: 'horizontal', variant: 'strong', class: { line: 'h-0.5' } },
    { orientation: 'vertical', variant: 'strong', class: { line: 'w-0.5' } },
  ],
  defaultVariants: { orientation: 'horizontal', variant: 'default', labelStyle: 'plain' },
});

export type SeparatorVariantProps = VariantProps<typeof separatorVariants>;

import type { ComponentDoc } from '../../doc';

export const doc: ComponentDoc = {
  name: 'Separator',
  group: 'Layout',
  status: 'stable',
  description: 'Thin rule between content. Horizontal or vertical, default / subtle / strong weight, and an optional label (plain text, mono kicker or pill) placed at the start, centre or end of a horizontal line.',
  primitive: '@base-ui/react/separator',
  pattern: 'separator',
  tokens: ['border', 'secondary', 'muted-foreground'],
};

/**
 * Component documentation contract. Every component folder exports a `*.doc.ts`
 * with this shape; the registry build and the docs site read it.
 */
export interface ComponentDoc {
  /** Public component name, e.g. "Button". */
  name: string;
  /** Inventory group, e.g. "Actions", "Forms", "Overlays". */
  group: 'Actions' | 'Forms' | 'Overlays' | 'Navigation' | 'Display' | 'Feedback' | 'Layout' | 'Theme';
  /** Lifecycle badge. */
  status: 'stable' | 'beta' | 'experimental';
  description: string;
  /** Headless primitive it is built on, if any (e.g. "@base-ui/react/dialog"). */
  primitive?: string;
  /** WAI-ARIA pattern the a11y contract test checks. */
  pattern?: string;
  /** Keyboard contract: key → behaviour. Each row is covered by a test. */
  keyboard?: Array<[key: string, behaviour: string]>;
  /** Tokens the component reads (for the theming docs). */
  tokens?: string[];
}
